const jobs = $input.all()[0].json.jobs_results || [];

const sanitizeUrl = (value = '') => {
  try {
    const u = new URL(String(value));
    return (u.protocol === 'https:' || u.protocol === 'http:') ? u.toString() : '';
  } catch {
    return '';
  }
};

const newItems = [];
for (const job of jobs) {
  let title = job.title || 'Unknown Title';
  let company = job.company_name || 'Unknown Company';
  let location = job.location || 'India';
  let pubDate = job.detected_extensions?.posted_at || 'Today';

  let link = '';
  if (job.apply_options && job.apply_options.length > 0) {
    link = job.apply_options[0].link;
  } else if (job.share_link) {
    link = job.share_link;
  }
  link = sanitizeUrl(link);
  if (!link) continue;

  const titleLower = title.toLowerCase();

  const hasExcluded = ["intern", "internship", "training", "unpaid", "senior", "lead"].some(kw => titleLower.includes(kw));
  if (hasExcluded) continue;

  let score = 0;
  if (titleLower.includes("fresher") || titleLower.includes("entry level") || titleLower.includes("junior")) score += 10;
  if (titleLower.includes("react") || titleLower.includes("backend") || titleLower.includes("node")) score += 5;

  newItems.push({
    json: {
      title,
      company,
      location,
      link,
      pubDate,
      relevanceScore: score
    }
  });
}

newItems.sort((a, b) => b.json.relevanceScore - a.json.relevanceScore);
return newItems;

const jobs = $input.all().map(i => i.json);

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const sanitizeUrl = (value = '') => {
  try {
    const u = new URL(String(value));
    return (u.protocol === 'https:' || u.protocol === 'http:') ? u.toString() : '';
  } catch {
    return '';
  }
};

if (jobs.length === 0) {
  return [{ json: { subject: "Daily Entry-Level Tech Jobs (0)", htmlContent: "<p>No new entry-level jobs found today across the web based on the criteria.</p>" } }];
}

let html = `
<div style="font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; color: #1a1a1a; max-width: 600px; margin: 0 auto;">
  <div style="background: linear-gradient(135deg, #0056b3, #003d82); padding: 20px; border-radius: 8px 8px 0 0;">
    <h2 style="color: #ffffff; margin: 0; font-size: 24px;">🌐 Global Tech Jobs Scan</h2>
    <p style="color: #e0e0e0; margin: 5px 0 0 0; font-size: 14px;">Fresh Entry-Level Roles in India</p>
  </div>

  <div style="padding: 20px; background-color: #ffffff; border: 1px solid #e0e0e0; border-top: none; border-radius: 0 0 8px 8px;">
    <p style="font-size: 16px; margin-bottom: 20px;">Here are the top ${jobs.length} jobs scraped from Google Jobs in the last 24 hours:</p>
`;

for (const job of jobs) {
  const safeTitle = escapeHtml(job.title || 'Unknown Title');
  const safeCompany = escapeHtml(job.company || 'Unknown Company');
  const safeLocation = escapeHtml(job.location || 'India');
  const safePubDate = escapeHtml(job.pubDate || 'Today');
  const safeScore = escapeHtml(String(job.relevanceScore ?? '0'));
  const safeLink = sanitizeUrl(job.link || '');

  html += `
    <div style="margin-bottom: 15px; padding: 15px; background-color: #f8f9fa; border-radius: 6px; border-left: 4px solid #0056b3; transition: transform 0.2s;">
      <h3 style="margin: 0 0 8px 0; color: #2c3e50; font-size: 18px;">${safeTitle}</h3>
      <div style="color: #555; font-size: 14px; margin-bottom: 12px;">
        <p style="margin: 4px 0;"><span style="font-weight: 600; color: #333;">🏢 Company:</span> ${safeCompany}</p>
        <p style="margin: 4px 0;"><span style="font-weight: 600; color: #333;">📍 Location:</span> ${safeLocation}</p>
        <p style="margin: 4px 0;"><span style="font-weight: 600; color: #333;">⏳ Posted:</span> ${safePubDate}</p>
        <p style="margin: 4px 0;"><span style="font-weight: 600; color: #333;">⭐ Relevance Score:</span> ${safeScore}</p>
      </div>
      <a href="${safeLink || '#'}" style="display: inline-block; padding: 8px 16px; background-color: #0056b3; color: #ffffff; text-decoration: none; border-radius: 4px; font-weight: 600; font-size: 14px;">Apply Now</a>
    </div>
  `;
}

html += `
    <p style="font-size: 12px; color: #888; text-align: center; margin-top: 30px;">Automated by n8n • Powered by Google Jobs</p>
  </div>
</div>
`;

return [{ json: { subject: `🎯 Daily Entry-Level Tech Jobs (${jobs.length})`, htmlContent: html } }];
